import { hmac as hmacNoble } from '@noble/hashes/hmac.js'

import { assertHmacParams } from './utils/assertHash.mjs'
import { hash as hashNoble } from './utils/hash.noble.mjs'
import { fromUint8orString, parseHashInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'

/** @deprecated Use async `hmac()` */
export function hmacSync(type, secret, data, form = 'buffer') {
  assertHmacParams(type, secret, form)
  secret = fromUint8orString(secret) // eslint-disable-line no-param-reassign
  data = parseHashInput(data) // eslint-disable-line no-param-reassign

  if (Array.isArray(data)) {
    const state = hmacNoble.create(hashNoble(type), secret)
    for (const entry of data) state.update(entry) // checked to be uint8arr
    return fromUint8Super(state.digest(), form)
  }
  const result = hmacNoble(hashNoble(type), secret, data)
  return fromUint8Super(result, form)
}

export const hmac = async (type, secret, data, form) => hmacSync(type, secret, data, form)
